(function initThemeSingleton() {
  const docEl = document.documentElement;
  docEl.setAttribute('data-theme', 'light');
  docEl.classList.remove('dark');
  docEl.classList.add('light', 'light-theme');

  function updateIcons(theme) {
    const sun = document.getElementById('theme-toggle-sun');
    const moon = document.getElementById('theme-toggle-moon');
    if (sun && moon) {
      sun.style.display = 'block';
      moon.style.display = 'none';
    } else {
      const btn = document.getElementById('theme-toggle');
      if (btn) {
        btn.textContent = '☀️';
      }
    }
  }

  window.toggleTheme = function(e) {
    if (e) {
      e.preventDefault();
      e.stopImmediatePropagation();
    }
    docEl.setAttribute('data-theme', 'light');
    docEl.classList.remove('dark');
    docEl.classList.add('light', 'light-theme');
    try {
      localStorage.setItem('campussense_theme', 'light');
    } catch (err) {}
    updateIcons('light');
  };

  function setupThemeToggle() {
    document.body.classList.remove('modal-open');
    document.body.style.overflow = '';
    const btn = document.getElementById('theme-toggle');
    if (btn) {
      btn.onclick = window.toggleTheme;
    }
    updateIcons('light');
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', setupThemeToggle);
  } else {
    setupThemeToggle();
  }
})();

function lockBodyScroll(lock) {
  if (lock) {
    document.body.classList.add('modal-open');
  } else {
    document.body.classList.remove('modal-open');
  }
}
window.lockBodyScroll = lockBodyScroll;

function safeBind(selector, event, handler) {
  try {
    document.querySelectorAll(selector).forEach(el => {
      el.addEventListener(event, (e) => {
        try {
          handler(e, el);
        } catch (err) {
          console.error(`Error on ${selector}:`, err);
        }
      });
    });
  } catch (err) {
    console.error(`Error querying selector ${selector}:`, err);
  }
}
window.safeBind = safeBind;

