    window.previewPdfFile = function(rawUrl, title) {
      const isSyllabus = isSyllabusResource(rawUrl, title);
      if (!isSyllabus && !isUserAuthenticated()) {
        try {
            sessionStorage.setItem('pending_download_action', JSON.stringify({
                action: 'preview',
                title: title || 'MAKAUT Resource',
                fileUrl: rawUrl
            }));
        } catch (e) {}
        window.location.href = '/login.html';
        return;
      }

      const modal = document.getElementById('pdf-preview-modal') || document.getElementById('pdf-viewer-modal') || document.getElementById('pdf-modal');
      let iframe = document.getElementById('pdf-viewer-frame');
      const titleEl = document.getElementById('pdf-preview-title') || document.getElementById('pdf-modal-title');
      const openNewTabBtn = document.getElementById('btn-pdf-open-external');
      const downloadBtn = document.getElementById('btn-pdf-download-direct') || document.getElementById('btn-pdf-external-download');

      if (!modal) {
        window.open(normalizePdfUrl(rawUrl), '_blank');
        return;
      }

      if (!iframe) iframe = modal.querySelector('iframe');
      const resolvedUrl = normalizePdfUrl(rawUrl);

      // 1. Update text and direct action links
      if (titleEl) titleEl.textContent = title || 'Document Preview';
      if (openNewTabBtn) {
        openNewTabBtn.href = resolvedUrl;
        openNewTabBtn.target = '_blank';
      }
      if (downloadBtn) {
        downloadBtn.href = resolvedUrl;
        downloadBtn.setAttribute('download', '');
      }

      // 2. Clear previous iframe state to prevent black screen freeze
      if (iframe) iframe.src = 'about:blank';

      // 3. Make modal visible first so the DOM calculates geometry
      modal.style.display = 'flex';
      modal.classList.add('active');
      modal.style.zIndex = '99999';
      document.body.classList.add('modal-open');
      if (typeof lockBodyScroll === 'function') {
        lockBodyScroll(true);
      }

      // 4. Defer setting iframe src until modal layout is calculated
      setTimeout(() => {
        if (iframe) {
          // Append toolbar parameters for clean viewport display
          iframe.src = resolvedUrl + '#toolbar=1&navpanes=0';
        }
      }, 60);
    };

    async function downloadPdfFile(fileUrl, preferredName) {
        const isSyllabus = isSyllabusResource(fileUrl, preferredName);
        if (!isSyllabus && !isUserAuthenticated()) {
            try {
                sessionStorage.setItem('pending_download_action', JSON.stringify({
                    action: 'download',
                    title: preferredName || 'MAKAUT Resource',
                    fileUrl: fileUrl
                }));
            } catch (e) {}
            window.location.href = '/login.html';
            return;
        }
        if (!requireAuthOrTrigger()) return;
        const resolved = resolveAssetPath(fileUrl);
        try {
            const res = await fetch(resolved);
            if (!res.ok) throw new Error(`HTTP ${res.status}`);
            const blob = await res.blob();
            const blobUrl = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = blobUrl;
            a.download = preferredName || resolved.split('/').pop();
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            setTimeout(() => URL.revokeObjectURL(blobUrl), 1500);
        } catch (err) {
            console.warn('Blob download failed, using direct anchor fallback:', err);
            const a = document.createElement('a');
            a.href = resolved;
            a.download = preferredName || '';
            a.target = '_blank';
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
        }
    }
    window.downloadPdfFile = downloadPdfFile;

    // ==========================================
    // 3. State Machine & User Context
    // ==========================================
    let isLoggedIn = localStorage.getItem('campussense_logged_in') === 'true';
    let userIdentifier = localStorage.getItem('campussense_user_id') || ('student-' + Math.random().toString(36).substring(2, 11));
    let userName = localStorage.getItem('campussense_user_name') || 'Student';
    let currentRegulation = localStorage.getItem('campussense_regulation') || '2026';
    let currentYearMode = localStorage.getItem('campussense_year_mode') || 'FIRST_YEAR';
    if (currentYearMode === 'UPPER_YEARS') {
        currentYearMode = 'DEPARTMENTAL_YEARS';
        localStorage.setItem('campussense_year_mode', 'DEPARTMENTAL_YEARS');
    }
    let currentStream = localStorage.getItem('campussense_stream') || (currentYearMode === 'FIRST_YEAR' ? 'FIRST_YEAR' : 'CSE');
    let currentSem = parseInt(localStorage.getItem('campussense_semester') || (currentYearMode === 'FIRST_YEAR' ? '1' : '5'), 10);
    let userChecklistState = {};
    try {
        userChecklistState = JSON.parse(localStorage.getItem('campussense_checklist_state') || '{}');
    } catch (e) {
        userChecklistState = {};
    }
    let savedBookmarks = [];
    try {
        savedBookmarks = JSON.parse(localStorage.getItem('campussense_saved_deck') || '[]');
    } catch (e) {
        savedBookmarks = [];
    }
    const CANONICAL_DEFAULT_DECK = [
        {
            code: 'PCC-CS501',
            title: 'Pumping Lemma Repeated Proofs (2018-2023)',
            tag: 'HIGH PROBABILITY 92%',
            details: '8 Solved Contradictions • Regular/CFL',
            pages: '6 Pages'
        },
        {
            code: 'PCC-CS502',
            title: 'BCNF Decomposition & Dependency Preservation Proofs',
            tag: '15 MARKS SURE-SHOT 88%',
            details: '5 Solved Numerical Sets • Armstrong Axioms',
            pages: '4 Pages'
        },
        {
            code: 'PCC-CS503',
            title: 'Dining Philosophers with Counting Semaphores in C',
            tag: '78% CONFIDENCE',
            details: 'Deadlock-free Implementation • POSIX',
            pages: '3 Pages'
        },
        {
            code: 'PCC-CS504',
            title: 'Java Multithreading Lifecycle & Synchronization Locks',
            tag: 'VIVA & WRITTEN 85%',
            details: 'Thread states, join(), wait(), notifyAll()',
            pages: '5 Pages'
        }
    ];
    if (!savedBookmarks || savedBookmarks.length === 0) {
        savedBookmarks = [...CANONICAL_DEFAULT_DECK];
    }

    localStorage.setItem('campussense_user_id', userIdentifier);
    localStorage.setItem('campussense_year_mode', currentYearMode);

    function getActiveAcademicSubject(preferredSem = null) {
        try {
            const stored = localStorage.getItem('campussense_academic_profile');
            let stream = currentStream || 'CSE';
            let sem = preferredSem || currentSem || 3;
            let yearMode = currentYearMode;
            if (stored) {
                const prof = JSON.parse(stored);
                if (prof.stream) stream = prof.stream;
                if (prof.semester) sem = parseInt(prof.semester, 10);
                if (prof.yearMode) yearMode = prof.yearMode;
            }
            if (stream === 'CSE' && (yearMode !== 'FIRST_YEAR' || sem >= 3)) {
                const cseCourses = (typeof DEPARTMENT_STREAMS !== 'undefined' && DEPARTMENT_STREAMS['CSE'] && DEPARTMENT_STREAMS['CSE'].courses) ||
                                  (typeof OFFICIAL_CSE_COURSES !== 'undefined' ? OFFICIAL_CSE_COURSES : []);
                const semCourses = cseCourses.filter(c => c.semester === sem);
                if (semCourses.length > 0) return semCourses[0];
                if (cseCourses.length > 0) return cseCourses[0];
            }
        } catch (e) {}
        return (typeof MAKAUT_CURRICULUM !== 'undefined' && MAKAUT_CURRICULUM.length > 0) ? MAKAUT_CURRICULUM[0] : null;
    }
    window.getActiveAcademicSubject = getActiveAcademicSubject;

    function syncCatalogIntoCourses(resources) {
        if (!Array.isArray(resources) || resources.length === 0) return;
        window._catalogResources = resources;

        resources.forEach(r => {
            if (r.resourceType !== 'PYQ' || !r.fileUrl) return;

            const streamKey = (r.stream || '').toUpperCase();
            const year = r.year || 2024;
            const title = r.title || 'Examination Paper';
            const sem = r.semester;
            const codeNorm = (r.subjectCode || '').toLowerCase().replace(/[^a-z0-9]/g, '');
            const nameNorm = (r.subjectName || '').toLowerCase().replace(/[^a-z0-9]/g, '');

            let matchedCourse = null;

            if (streamKey === 'FIRST_YEAR' || streamKey === 'COMMON') {
                const curriculum = window.MAKAUT_CURRICULUM || (typeof MAKAUT_CURRICULUM !== 'undefined' ? MAKAUT_CURRICULUM : []);
                for (const c of curriculum) {
                    const cCodeNorm = (c.code || '').toLowerCase().replace(/[^a-z0-9]/g, '');
                    const cAltNorm = (c.altCode || '').toLowerCase().replace(/[^a-z0-9]/g, '');
                    const cNameNorm = (c.name || c.title || '').toLowerCase().replace(/[^a-z0-9]/g, '');
                    if (cCodeNorm === codeNorm || cAltNorm === codeNorm || cNameNorm.includes(codeNorm) || (nameNorm && cNameNorm.includes(nameNorm))) {
                        matchedCourse = c;
                        break;
                    }
                }
            } else {
                const streamObj = window.DEPARTMENT_STREAMS?.[streamKey] || 
                                  window.DEPARTMENT_STREAMS?.[streamKey.replace('-', '')] ||
                                  window.DEPARTMENT_STREAMS?.[r.stream?.toLowerCase()];
                if (streamObj && Array.isArray(streamObj.courses)) {
                    for (const c of streamObj.courses) {
                        const cCodeNorm = (c.code || '').toLowerCase().replace(/[^a-z0-9]/g, '');
                        const cAltNorm = (c.altCode || '').toLowerCase().replace(/[^a-z0-9]/g, '');
                        const cNameNorm = (c.name || c.title || '').toLowerCase().replace(/[^a-z0-9]/g, '');
                        if (c.semester === sem && (cCodeNorm === codeNorm || cAltNorm === codeNorm || (codeNorm && cNameNorm.includes(codeNorm)))) {
                            matchedCourse = c;
                            break;
                        }
                    }
                    if (!matchedCourse) {
                        for (const c of streamObj.courses) {
                            const cCodeNorm = (c.code || '').toLowerCase().replace(/[^a-z0-9]/g, '');
                            const cAltNorm = (c.altCode || '').toLowerCase().replace(/[^a-z0-9]/g, '');
                            if (cCodeNorm === codeNorm || cAltNorm === codeNorm) {
                                matchedCourse = c;
                                break;
                            }
                        }
                    }
                    if (!matchedCourse) {
                        matchedCourse = {
                            code: r.subjectCode || 'ELECTIVE',
                            name: r.subjectName || title,
                            department: streamObj.name,
                            stream: streamKey,
                            semester: sem || 3,
                            credits: 3,
                            syllabusUrl: streamObj.syllabusPath || '',
                            pyqs: []
                        };
                        streamObj.courses.push(matchedCourse);
                    }
                }
            }

            if (matchedCourse) {
                if (!Array.isArray(matchedCourse.pyqs)) matchedCourse.pyqs = [];
                const normFile = normalizePdfUrl(r.fileUrl);
                const exists = matchedCourse.pyqs.some(p => {
                    return p.fileUrl === r.fileUrl || 
                           normalizePdfUrl(p.fileUrl) === normFile ||
                           (p.year === year && (p.title || '').toLowerCase() === title.toLowerCase());
                });
                if (!exists) {
                    matchedCourse.pyqs.push({
                        id: r.id,
                        year: year,
                        type: 'END_SEM',
                        title: title,
                        fileUrl: r.fileUrl
                    });
                }
            }
        });

        if (window.DEPARTMENT_STREAMS) {
            Object.values(window.DEPARTMENT_STREAMS).forEach(stream => {
                if (stream && Array.isArray(stream.courses)) {
                    stream.pyqs = stream.courses.flatMap(c => c.pyqs || []);
                }
            });
        }

        if (typeof buildUnifiedSearchIndex === 'function') {
            buildUnifiedSearchIndex();
        }
    }
    window.syncCatalogIntoCourses = syncCatalogIntoCourses;

    async function updateLandingLiveMetrics() {
        try {
            const subjectsEl = document.getElementById('metric-subjects-count') || document.getElementById('stat-subjects-count');
            const pyqsEl = document.getElementById('metric-pyqs-count') || document.getElementById('stat-pyqs-count');

            let subjectsCount = 122;
            let pyqsCount = 1462;

            let data = null;
            // 1. Try backend dynamic API first
            try {
                const apiRes = await fetch('/api/resources');
                if (apiRes.ok) {
                    data = await apiRes.json();
                }
            } catch (e) {}

            // 2. Fall back to static resources.json
            if (!data && typeof fetch === 'function') {
                try {
                    const res = await fetch('resources.json');
                    if (res.ok) {
                        data = await res.json();
                    }
                } catch (e) {}
            }

            if (data && Array.isArray(data.resources)) {
                syncCatalogIntoCourses(data.resources);
                if (data.summary && typeof data.summary.pyqCount === 'number') {
                    pyqsCount = data.summary.pyqCount;
                } else {
                    const pyqs = data.resources.filter(r => r.resourceType === 'PYQ');
                    if (pyqs.length > 0) pyqsCount = pyqs.length;
                }
                const pyqs = data.resources.filter(r => r.resourceType === 'PYQ');
                const uniqueSubs = new Set(pyqs.map(r => r.subjectCode).filter(Boolean));
                if (uniqueSubs.size > 0) subjectsCount = uniqueSubs.size;
            } else if (window._catalogResources && Array.isArray(window._catalogResources)) {
                syncCatalogIntoCourses(window._catalogResources);
            }

            if (subjectsEl) {
                subjectsEl.textContent = String(subjectsCount);
            }
            if (pyqsEl) {
                pyqsEl.textContent = String(pyqsCount);
            }
        } catch (err) {
            console.warn("Could not calculate dynamic landing metrics:", err);
        }
    }
    window.updateLandingLiveMetrics = updateLandingLiveMetrics;

    function bindAcademicSetupOptions() {
        ['.stream-pill', '.sem-pill', '.college-card', '.stream-option', '.sem-btn'].forEach(selector => {
            document.querySelectorAll(selector).forEach(el => {
                if (el.classList.contains('academic-stage-card') || el.classList.contains('stage-card') || el.hasAttribute('data-stage') || el.classList.contains('primary-year-btn')) {
                    return;
                }
                el.onclick = function(e) {
                    const parent = el.parentElement;
                    if (parent) {
                        parent.querySelectorAll(selector).forEach(sib => sib.classList.remove('selected', 'active'));
                    }
                    el.classList.add('selected', 'active');
                };
            });
        });
    }
    window.bindAcademicSetupOptions = bindAcademicSetupOptions;

