    DEPARTMENT_STREAMS['csds'] = DEPARTMENT_STREAMS['CSDS'];
    DEPARTMENT_STREAMS['csbs'] = DEPARTMENT_STREAMS['CSBS'];
    DEPARTMENT_STREAMS['cse'] = DEPARTMENT_STREAMS['CSE'];
    DEPARTMENT_STREAMS['it'] = DEPARTMENT_STREAMS['IT'];
    DEPARTMENT_STREAMS['cse-aiml'] = DEPARTMENT_STREAMS['CSE-AIML'];
    window.DEPARTMENT_STREAMS = DEPARTMENT_STREAMS;

    function updateContextUI() {
        const labelEl = document.getElementById('nav-academic-label') || document.getElementById('current-context-text');
        if (labelEl) {
            if (currentYearMode === 'FIRST_YEAR') {
                labelEl.textContent = '1st Year Common • Sem 1 & 2';
            } else {
                const streamLabel = currentStream || 'CSE';
                labelEl.textContent = `${streamLabel} • Sem ${currentSem || 3}`;
            }
        }
        const fallbackEl = document.getElementById('current-context-text');
        if (fallbackEl && fallbackEl !== labelEl) {
            fallbackEl.textContent = labelEl ? labelEl.textContent : `CSE • Sem ${currentSem || 3}`;
        }
        const userDisplayEl = document.getElementById('user-profile-name') || document.getElementById('user-display-name');
        if (userDisplayEl) {
            userDisplayEl.textContent = userName;
        }

        const isAuth = !!(window.Clerk?.user || window.isLoggedIn || localStorage.getItem('campussense_logged_in') === 'true');
        const signOutBtn = document.getElementById('btn-dashboard-sign-out') || document.getElementById('clerk-sign-out-btn');
        if (signOutBtn) {
            signOutBtn.style.display = isAuth ? 'inline-flex' : 'none';
            signOutBtn.onclick = window.handleSignOut;
        }
        const signInBtn = document.getElementById('btn-sign-in');
        const signUpBtn = document.getElementById('btn-sign-up');
        if (signInBtn) signInBtn.style.display = isAuth ? 'none' : '';
        if (signUpBtn) signUpBtn.style.display = isAuth ? 'none' : '';
    }
    window.updateContextUI = updateContextUI;
    updateContextUI();

